reference_solution:
def numSubarraysWithSum(nums, goal):
    seen = {0: 1}
    total = count = 0
    for x in nums:
        total += x
        count += seen.get(total - goal, 0)
        seen[total] = seen.get(total, 0) + 1
    return count

brute_force_solution:
def numSubarraysWithSum(nums, goal):
    count = 0
    for i in range(len(nums)):
        s = 0
        for j in range(i, len(nums)):
            s += nums[j]
            if s == goal:
                count += 1
    return count

